import 'package:flutter_test/flutter_test.dart';
import 'package:notees/domain/services/srs.dart';

/// Mirrors `packages/domain/test/srs.test.ts` exactly (same TODAY, same
/// vectors) plus Dart-port edge arms: month/year rollover in the UTC day
/// math and dayDiff across UTC month/year boundaries. The exact numeric
/// expectations in the edge arms were generated by running the TypeScript
/// implementation itself, so they pin bit-for-bit parity.
void main() {
  const today = '2026-10-28';

  group('sm2', () {
    test('first good: reps 1, interval 1, due tomorrow, ease 2.5', () {
      final s = nextCardState(unseenCardState, CardGrade.good, SrsAlgorithm.sm2, today);
      expect(
        s,
        const CardSrsState(
          due: '2026-10-29',
          reps: 1,
          interval: 1,
          ease: 2.5,
          difficulty: null,
          stability: null,
        ),
      );
    });

    test('lapse resets reps and interval, floors ease at 1.3', () {
      const reviewed = CardSrsState(
        due: '2026-10-28',
        reps: 5,
        interval: 21,
        ease: 1.35,
      );
      final s = nextCardState(reviewed, CardGrade.again, SrsAlgorithm.sm2, today);
      expect(s.reps, 0);
      expect(s.interval, 1);
      expect(s.ease, 1.3);
    });
  });

  group('fsrs', () {
    test('first good initializes difficulty and stability, not null', () {
      final s = nextCardState(unseenCardState, CardGrade.good, SrsAlgorithm.fsrs, today);
      expect(s.ease, isNull); // sm2 field untouched
      expect(s.difficulty, isNotNull);
      expect(s.stability, greaterThan(0));
      expect(s.due, today); // same-day re-view for first fsrs step
    });

    test('Review Focus 3: sm2-reviewed card graded under fsrs initializes fsrs fields, keeps ease', () {
      final sm2 = nextCardState(unseenCardState, CardGrade.good, SrsAlgorithm.sm2, today);
      final fsrs = nextCardState(
        CardSrsState(
          due: sm2.due,
          reps: sm2.reps,
          interval: sm2.interval,
          ease: sm2.ease,
        ),
        CardGrade.good,
        SrsAlgorithm.fsrs,
        today,
      );
      expect(fsrs.ease, 2.5); // stale sm2 field preserved, not corrupted
      expect(fsrs.stability, isNotNull);
    });
  });

  group('isCardStateDue', () {
    test('unseen cards are due; future-dated are not', () {
      expect(isCardStateDue(unseenCardState, today), isTrue);
      expect(isCardStateDue(const CardSrsState(due: '2026-10-29', reps: 0, interval: 0), today), isFalse);
      expect(isCardStateDue(const CardSrsState(due: today, reps: 0, interval: 0), today), isTrue);
    });
  });

  group('edge arms (Dart port — exact vectors from the TS implementation)', () {
    test('addDays month rollover: lapse on 2026-11-30 is due 2026-12-01', () {
      const reviewed = CardSrsState(due: '2026-11-30', reps: 5, interval: 21, ease: 1.35);
      final s = nextCardState(reviewed, CardGrade.again, SrsAlgorithm.sm2, '2026-11-30');
      expect(s.due, '2026-12-01');
      expect(s.reps, 0);
      expect(s.interval, 1);
      expect(s.ease, 1.3);
    });

    test('addDays year rollover: lapse on 2026-12-31 is due 2027-01-01', () {
      const reviewed = CardSrsState(due: '2026-12-31', reps: 5, interval: 21, ease: 1.35);
      final s = nextCardState(reviewed, CardGrade.again, SrsAlgorithm.sm2, '2026-12-31');
      expect(s.due, '2027-01-01');
    });

    test('dayDiff across a month boundary: fsrs second review is identical to the TS output', () {
      const state = CardSrsState(
        due: '2026-09-30',
        reps: 1,
        interval: 5,
        difficulty: 5,
        stability: 5,
      );
      final s = nextCardState(state, CardGrade.good, SrsAlgorithm.fsrs, today);
      expect(s.due, '2027-01-04');
      expect(s.reps, 2);
      expect(s.interval, 68);
      expect(s.difficulty, 5);
      expect(s.stability, closeTo(67.63440781952679, 1e-9));
    });

    test('dayDiff across a year boundary: fsrs hard review is identical to the TS output', () {
      const state = CardSrsState(
        due: '2025-12-31',
        reps: 1,
        interval: 10,
        difficulty: 5,
        stability: 5,
      );
      final s = nextCardState(state, CardGrade.hard, SrsAlgorithm.fsrs, today);
      expect(s.due, '2027-03-08');
      expect(s.reps, 2);
      expect(s.difficulty, closeTo(6.4604, 1e-9));
      expect(s.stability, closeTo(131.23387832988777, 1e-9));
    });

    test('near due date (no boundary) matches the TS output for comparison', () {
      const state = CardSrsState(
        due: '2026-10-27',
        reps: 1,
        interval: 5,
        difficulty: 5,
        stability: 5,
      );
      final s = nextCardState(state, CardGrade.good, SrsAlgorithm.fsrs, today);
      expect(s.due, '2026-11-17');
      expect(s.interval, 20);
      expect(s.stability, closeTo(19.800459243772405, 1e-9));
    });

    test('fsrs first-review arm for every grade matches the TS output', () {
      const unseen = CardSrsState(reps: 0, interval: 0);
      final again = nextCardState(unseen, CardGrade.again, SrsAlgorithm.fsrs, today);
      expect(again.due, today);
      expect(again.reps, 0);
      expect(again.interval, 0);
      expect(again.difficulty, closeTo(7.1949, 1e-9));
      expect(again.stability, closeTo(0.40255, 1e-9));

      final easy = nextCardState(unseen, CardGrade.easy, SrsAlgorithm.fsrs, today);
      expect(easy.reps, 1);
      expect(easy.stability, closeTo(15.69105, 1e-9));
    });

    test('mid-deck switch the other way: fsrs-graded card under sm2 keeps fsrs fields stale', () {
      final fsrs = nextCardState(unseenCardState, CardGrade.good, SrsAlgorithm.fsrs, today);
      final sm2 = nextCardState(
        CardSrsState(
          due: fsrs.due,
          reps: fsrs.reps,
          interval: fsrs.interval,
          difficulty: fsrs.difficulty,
          stability: fsrs.stability,
        ),
        CardGrade.good,
        SrsAlgorithm.sm2,
        today,
      );
      expect(sm2.ease, 2.5);
      expect(sm2.due, '2026-11-03');
      expect(sm2.interval, 6);
      expect(sm2.difficulty, closeTo(7.1949, 1e-9)); // untouched
      expect(sm2.stability, closeTo(3.173, 1e-9)); // untouched
    });

    test('sm2 hard/ease vectors match the TS output (interval uses the pre-update ease)', () {
      const state = CardSrsState(
        due: '2026-10-20',
        reps: 3,
        interval: 10,
        ease: 2.2,
      );
      final hard = nextCardState(state, CardGrade.hard, SrsAlgorithm.sm2, today);
      expect(hard.due, '2026-11-19');
      expect(hard.reps, 4);
      expect(hard.interval, 22);
      expect(hard.ease, closeTo(2.0600000000000005, 1e-12));

      final easy = nextCardState(state, CardGrade.easy, SrsAlgorithm.sm2, today);
      expect(easy.interval, 22); // round(10 * 2.2) with the OLD ease
      expect(easy.ease, closeTo(2.3000000000000003, 1e-12));
    });
  });

  group('parseSrsAlgorithm', () {
    test('accepts the wire scalars only', () {
      expect(parseSrsAlgorithm('sm2'), SrsAlgorithm.sm2);
      expect(parseSrsAlgorithm('fsrs'), SrsAlgorithm.fsrs);
      expect(parseSrsAlgorithm('bogus'), isNull);
      expect(parseSrsAlgorithm(null), isNull);
      expect(SrsAlgorithm.sm2.wire, 'sm2');
      expect(SrsAlgorithm.fsrs.wire, 'fsrs');
    });
  });
}
